## Step 2 — Fuse

Validating webhooks in C++ ensures that incoming requests are authentic and haven't been tampered with. Since C++ lacks a built-in HTTP server or cryptography library, you will need an HTTP framework (like `cpp-httplib` or Crow) and **OpenSSL** for HMAC-SHA256 calculation.

Below is a complete, production-ready implementation combining signature verification, replay attack prevention, and secure timing practices.

### 1. The `WebhookValidator` Class

This class handles HMAC computation, constant-time string comparison, and timestamp validation.

```cpp
#include <openssl/hmac.h>
#include <openssl/evp.h>
#include <string>
#include <chrono>
#include <sstream>
#include <iomanip>

class WebhookValidator {
private:
    std::string secret;

    std::string computeHMAC(const std::string& payload) {
        unsigned char result[EVP_MAX_MD_SIZE];
        unsigned int length = 0;

        HMAC(EVP_sha256(), secret.c_str(), secret.length(),
             reinterpret_cast<const unsigned char*>(payload.c_str()), payload.length(),
             result, &length);

        std::stringstream ss;
        for (unsigned int i = 0; i < length; ++i) {
            ss << std::hex << std::setw(2) << std::setfill('0') << (int)result[i];
        }
        return ss.str();
    }

    // Constant-time comparison to prevent timing attacks
    bool constantTimeCompare(const std::string& a, const std::string& b) {
        if (a.length() != b.length()) return false;
        volatile unsigned char result = 0; // volatile prevents compiler optimization
        for (size_t i = 0; i < a.length(); ++i) {
            result |= a[i] ^ b[i];
        }
        return result == 0;
    }

public:
    WebhookValidator(const std::string& webhookSecret) : secret(webhookSecret) {}

    bool validateSignature(const std::string& payload, const std::string& signature,
                           const std::string& prefix = "sha256=") {
        std::string expectedSignature = computeHMAC(payload);

        // Strip prefix if present (e.g., "sha256=...")
        size_t pos = signature.find(prefix);
        std::string receivedSignature = (pos != std::string::npos)
            ? signature.substr(pos + prefix.length())
            : signature;

        return constantTimeCompare(expectedSignature, receivedSignature);
    }

    // Validate timestamps to prevent replay attacks (e.g., 5-minute window)
    bool validateTimestamp(const std::string& timestampHeader, int64_t maxAgeSeconds = 300) {
        try {
            int64_t timestamp = std::stoll(timestampHeader);
            int64_t now = std::chrono::duration_cast<std::chrono::seconds>(
                std::chrono::system_clock::now().time_since_epoch()).count();
            return (now - timestamp) <= maxAgeSeconds;
        } catch (...) {
            return false;
        }
    }

    bool validate(const std::string& payload, const std::string& signature,
                  const std::string& timestamp) {
        return validateSignature(payload, signature) && validateTimestamp(timestamp);
    }
};
```

### 2. HTTP Server Example (using `cpp-httplib`)

Always validate the signature against the **raw request body**. Parsing JSON before verifying the signature can alter whitespace or key ordering, resulting in a different HMAC hash and a failed validation.

```cpp
#include "httplib.h"
#include <iostream>

int main() {
    // Load from environment variables in production!
    const std::string WEBHOOK_SECRET = "your_webhook_secret_here";
    WebhookValidator validator(WEBHOOK_SECRET);

    httplib::Server server;

    server.Post("/webhook", [&validator](const httplib::Request& req, httplib::Response& res) {
        std::string signature = req.get_header_value("X-Hub-Signature-256");
        std::string timestamp = req.get_header_value("X-Hub-Signature-Timestamp");
        std::string payload = req.body; // Use raw body, not parsed JSON

        if (!validator.validate(payload, signature, timestamp)) {
            res.status = 401;
            res.set_content("Invalid webhook signature", "text/plain");
            return;
        }

        // Process valid webhook payload
        std::cout << "Valid webhook received: " << payload << std::endl;
        res.status = 200;
        res.set_content("OK", "text/plain");
    });

    std::cout << "Server running on port 8080..." << std::endl;
    server.listen("0.0.0.0", 8080);
    return 0;
}
```

