## 🤖 Android (Kotlin) – Using Retrofit + OkHttp

### 1. Dependencies & API Interface
```kotlin
// build.gradle
// implementation 'com.squareup.retrofit2:retrofit:2.9.0'
// implementation 'com.squareup.retrofit2:converter-gson:2.9.0'
// implementation 'com.squareup.okhttp3:logging-interceptor:4.11.0'

interface ApiService {
    @GET("users/{id}")
    suspend fun getUser(@Path("id") userId: Int): Response<User>
}

data class User(val id: Int, val name: String)
```

### 2. Network Engine (Interceptors & Client Setup)
```kotlin
object NetworkClient {
    private const val BASE_URL = "https://api.example.com/"

    private val loggingInterceptor = HttpLoggingInterceptor().apply {
        level = if (BuildConfig.DEBUG) HttpLoggingInterceptor.Level.BODY else HttpLoggingInterceptor.Level.NONE
    }

    private val authInterceptor = Interceptor { chain ->
        val token = TokenManager.getToken()
        val request = chain.request().newBuilder().apply {
            if (token != null) addHeader("Authorization", "Bearer $token")
        }.build()
        chain.proceed(request)
    }

    private val okHttpClient = OkHttpClient.Builder()
        .addInterceptor(loggingInterceptor)
        .addInterceptor(authInterceptor)
        .connectTimeout(30, TimeUnit.SECONDS)
        .readTimeout(30, TimeUnit.SECONDS)
        .build()

    val apiService: ApiService by lazy {
        Retrofit.Builder()
            .baseUrl(BASE_URL)
            .client(okHttpClient)
            .addConverterFactory(GsonConverterFactory.create())
            .build()
            .create(ApiService::class.java)
    }
}
```

### 3. Repository Layer & ViewModel
```kotlin
class UserRepository(private val apiService: ApiService = NetworkClient.apiService) {
    suspend fun getUser(id: Int): Result<User> = try {
        val response = apiService.getUser(id)
        if (response.isSuccessful && response.body() != null) {
            Result.success(response.body()!!)
        } else {
            Result.failure(Exception("HTTP ${response.code()}"))
        }
    } catch (e: Exception) {
        Result.failure(e)
    }
}

class UserViewModel : ViewModel() {
    private val repository = UserRepository()
    private val _userState = MutableStateFlow<UserState>(UserState.Loading)
    val userState: StateFlow<UserState> = _userState.asStateFlow()

    fun loadUser(id: Int) {
        viewModelScope.launch {
            _userState.value = UserState.Loading
            repository.getUser(id).fold(
                onSuccess = { _userState.value = UserState.Success(it) },
                onFailure = { _userState.value = UserState.Error(it.message ?: "Unknown error") }
            )
        }
    }
}

sealed class UserState {
    object Loading : UserState()
    data class Success(val user: User) : UserState()
    data class Error(val message: String) : UserState()
}
```

