## ✅ Production Checklist

- [ ] **Transactional Outbox:** Are jobs queued in the same transaction as the DB update?
- [ ] **Idempotency:** Does the worker check if the work is already done?
- [ ] **Gateway Idempotency:** Are you sending an `idempotency_key` to the payment provider?
- [ ] **Retries:** Is there an exponential backoff strategy for transient failures?
- [ ] **Unrecoverable Errors:** Are declined cards marked as failed without triggering retries?
- [ ] **Dead Letter Queue:** Is there a DLQ and alerts set up for permanently failed jobs?
- [ ] **Timeouts:** Have you set reasonable timeouts so a "hung" API call doesn't block workers forever?
- [ ] **Webhook Security:** Are webhook signatures verified and processed asynchronously?
- [ ] **Observability:** Do you have comprehensive logging (without PII) and metrics in place?

# Secure OAuth Token Storage in Mobile Apps

Storing OAuth tokens securely is critical to protecting user data and preventing unauthorized access. The golden rule is to **never store tokens in plain text** (e.g., `UserDefaults`, `SharedPreferences`, or local JSON files), as these are easily accessible on rooted or jailbroken devices. 

Below are platform-specific best practices, cross-platform options, and architectural rules for securing tokens.

---

## 🔐 iOS: Keychain Services
Apple's Keychain provides encrypted storage for sensitive data. Unlike `UserDefaults`, Keychain data is encrypted and can be configured to persist securely.

### Swift Implementation
Using the native `Security` framework can be verbose, but here is a clean implementation:

```swift
import Foundation
import Security

class TokenStorage {
    static let shared = TokenStorage()
    private let service = "com.yourapp.oauth"

    func storeToken(_ token: String) throws {
        let data = Data(token.utf8)
        let query: [String: Any] = [
            kSecClass as String: kSecClassGenericPassword,
            kSecAttrService as String: service,
            kSecAttrAccount as String: "access_token",
            kSecAttrAccessible as String: kSecAttrAccessibleWhenUnlockedThisDeviceOnly
        ]

        SecItemDelete(query as CFDictionary)
        let status = SecItemAdd(query as CFDictionary, nil)

        guard status == errSecSuccess else {
            throw TokenError.storageFailed
        }
    }

    func getToken() throws -> String? {
        let query: [String: Any] = [
            kSecClass as String: kSecClassGenericPassword,
            kSecAttrService as String: service,
            kSecAttrAccount as String: "access_token",
            kSecReturnData as String: true,
            kSecMatchLimit as String: kSecMatchLimitOne
        ]

        var result: AnyObject?
        let status = SecItemCopyMatching(query as CFDictionary, &result)

        guard status == errSecSuccess,
              let data = result as? Data,
              let token = String(data: data, encoding: .utf8) else {
            return nil
        }

        return token
    }

    func deleteToken() {
        let query: [String: Any] = [
            kSecClass as String: kSecClassGenericPassword,
            kSecAttrService as String: service,
            kSecAttrAccount as String: "access_token"
        ]
        SecItemDelete(query as CFDictionary)
    }
}

enum TokenError: Error {
    case storageFailed
}
```

---

## 🤖 Android: EncryptedSharedPreferences
On Android, use **Jetpack Security**, which provides `EncryptedSharedPreferences`. This wraps the standard `SharedPreferences` but encrypts both keys and values using the **Android Keystore System**.

### Add Dependency (`build.gradle`)
```gradle
dependencies {
    implementation "androidx.security:security-crypto:1.1.0-alpha06"
}
```

### Kotlin Implementation
```kotlin
import android.content.Context
import androidx.security.crypto.EncryptedSharedPreferences
import androidx.security.crypto.MasterKey

class SecureTokenStorage(context: Context) {
    private val masterKey = MasterKey.Builder(context)
        .setKeyScheme(MasterKey.KeyScheme.AES256_GCM)
        .build()

    private val sharedPreferences = EncryptedSharedPreferences.create(
        context,
        "secure_tokens",
        masterKey,
        EncryptedSharedPreferences.PrefKeyEncryptionScheme.AES256_SIV,
        EncryptedSharedPreferences.PrefValueEncryptionScheme.AES256_GCM
    )

    fun storeToken(accessToken: String, refreshToken: String?, expiresAt: Long) {
        sharedPreferences.edit().apply {
            putString("access_token", accessToken)
            refreshToken?.let { putString("refresh_token", it) }
            putLong("expires_at", expiresAt)
            apply()
        }
    }

    fun getAccessToken(): String? = sharedPreferences.getString("access_token", null)
    fun getRefreshToken(): String? = sharedPreferences.getString("refresh_token", null)
    fun getExpiresAt(): Long = sharedPreferences.getLong("expires_at", 0)

    fun isTokenExpired(): Boolean {
        return System.currentTimeMillis() >= getExpiresAt()
    }

    fun clearTokens() {
        sharedPreferences.edit().clear().apply()
    }
}
```

---

## 📱 Cross-Platform Options
If you are using a cross-platform framework, do not write your own wrappers; use these community-vetted libraries that map to the native secure storages mentioned above:

*   **React Native:** [`react-native-keychain`](https://github.com/oblador/react-native-keychain)
*   **Flutter:** [`flutter_secure_storage`](https://pub.dev/packages/flutter_secure_storage)
*   **Expo:** [`expo-secure-store`](https://docs.expo.dev/versions/latest/sdk/secure-store/)

---

## 🔁 Token Refresh Strategy
Keep `access_tokens` short-lived (e.g., 1 hour). When a request receives a `401 Unauthorized`, retrieve the `refresh_token` from secure storage, request a new `access_token`, update the storage, and retry the request.

```kotlin
// Android Example
class TokenManager(private val context: Context, private val apiService: ApiService) {
    private val storage = SecureTokenStorage(context)

    suspend fun getValidAccessToken(): String? {
        if (!storage.isTokenExpired()) {
            return storage.getAccessToken()
        }

        val refreshToken = storage.getRefreshToken() ?: return null
        return try {
            val response = apiService.refreshToken(refreshToken)
            storage.storeToken(
                accessToken = response.accessToken,
                refreshToken = response.refreshToken,
                expiresAt = System.currentTimeMillis() + (response.expiresIn * 1000)
            )
            response.accessToken
        } catch (e: Exception) {
            storage.clearTokens()
            null
        }
    }

    fun logout() {
        storage.clearTokens()
    }
}
```

---

## ⚠️ What NOT to Do
```swift
// ❌ DON'T: Store in UserDefaults
UserDefaults.standard.set(token, forKey: "access_token")

// ❌ DON'T: Log tokens to the console
print("Token: \(token)")

// ❌ DON'T: Store in plain text files
let path = ".../token.txt"
try token.write(toFile: path, atomically: true, encoding: .utf8)
```

---

## ✅ Security Checklist & Best Practices
Beyond just storage, follow these architectural rules to maximize security:

| Risk / Practice | Solution / Description |
| :--- | :--- |
| **Use Secure Storage** | Always use Keychain (iOS) or EncryptedSharedPreferences (Android). |
| **Token Theft from RAM** | Clear tokens from memory variables as soon as they are written to secure storage. |
| **Man-in-the-Middle (MitM)** | Use **HTTPS** for all API calls and implement **SSL Pinning** to ensure the app only talks to your specific server certificate. |
| **Long-lived Access** | Keep `access_tokens` short-lived. Use `refresh_tokens` to obtain new ones. |
| **Device Compromise** | For high-security apps (Banking/Health), require **Biometric Authentication** (FaceID/Fingerprint) before accessing the Keychain/EncryptedPrefs. |
| **Leaking in Logs** | Ensure your logging library (Logcat/NSLog) is disabled in production so tokens aren't printed. |
| **Token Revocation** | Clear tokens securely on logout and allow server-side invalidation of compromised tokens. |

To understand why Rust's ownership and borrowing system is preferred over Garbage Collection (GC) for concurrency, we must first clarify a common misconception: **Garbage Collection is designed to solve memory management, not concurrency.** 

A GC prevents memory leaks and "use-after-free" errors, but it does nothing to prevent **data races**. Rust’s ownership system, on the other hand, is designed to prevent both. 

Here is a breakdown of why Rust's approach is superior for concurrent programming, supported by code examples.

---

### 1. Preventing Data Races at Compile Time
The root cause of almost all concurrency bugs is the combination of **aliasing** (multiple pointers to the same data) and **mutation** (changing that data). 

*   **In GC languages (Java, Go, C#):** You can share a variable across multiple threads and mutate it. If you forget to use a lock or mutex, two threads might write to the same memory simultaneously, causing a data race. The GC ensures the memory stays alive, but it doesn't stop the logical error.
*   **In Rust:** The compiler enforces a strict rule: **You can have many immutable references OR exactly one mutable reference, but never both at the same time.** If you try to share mutable data without explicit synchronization, the code will simply not compile.

### 2. Deterministic Performance (No GC Pauses)
GCs must periodically pause the execution of a program to scan memory and reclaim unused objects. In highly concurrent systems, the GC must often synchronize all threads to reach a "safe point" before scanning. This creates non-deterministic latency spikes ("stop-the-world" pauses), which are unacceptable in real-time systems, game engines, or high-frequency trading.

Rust has no runtime GC. Memory is managed deterministically via RAII—meaning memory is freed the instant its owner goes out of scope. This results in predictable latency and zero runtime overhead for memory tracking.

### 3. Thread Safety Encoded in the Type System (`Send` and `Sync`)
Rust uses marker traits to encode concurrency rules directly into the type system:
*   **`Send`**: Indicates that ownership of a value can be safely transferred to another thread.
*   **`Sync`**: Indicates that it is safe for multiple threads to access a value via references simultaneously.

If you try to pass a non-thread-safe type (like `Rc<T>`—a non-atomic reference counter) into another thread, **the code will not compile.** In GC languages, these threading bugs are often only discovered at runtime.

---

### Code Examples: Safe vs. Unsafe Concurrency

#### The "Wrong" Way (What GC languages allow)
In a GC language like Go, sharing a variable is easy. If you forget to use a `Mutex`, the code compiles and runs, but contains a data race that yields non-deterministic results.

```go
package main

import (
    "sync"
    "fmt"
)

func main() {
    var counter int
    var wg sync.WaitGroup

    // BUG: No mutex used. This is a data race.
    for i := 0; i < 10; i++ {
        wg.Add(1)
        go func() {
            defer wg.Done()
            counter++ // Unsafe concurrent write
        }()
    }

    wg.Wait()
    fmt.Println(counter) // Result is non-deterministic
}
```

#### The Rust Way (Compile-Time Prevention)
In Rust, you cannot share `counter` directly. You must wrap it in an `Arc` (Atomic Reference Counted) for shared ownership and a `Mutex` for safe mutation. **If you try to remove the Mutex, the code fails to compile.**

```rust
use std::sync::{Arc, Mutex};
use std::thread;

fn main() {
    // Arc allows multiple threads to own the data
    // Mutex ensures only one thread can mutate the data at a time
    let counter = Arc::new(Mutex::new(0));
    let mut handles = vec![];

    for _ in 0..10 {
        let counter_clone = Arc::clone(&counter);

        let handle = thread::spawn(move || {
            // lock() blocks until the mutex is available
            let mut num = counter_clone.lock().unwrap();
            *num += 1;
            // MutexGuard is dropped here, releasing the lock automatically
        });

        handles.push(handle);
    }

    for handle in handles {
        handle.join().unwrap();
    }

    println!("Result: {}", *counter.lock().unwrap());
}
```

#### Preventing Non-Thread-Safe Types
If you attempt to use standard reference counting (`Rc`) instead of atomic counting (`Arc`), Rust stops you immediately because `Rc` does not implement the `Send` trait.

```rust
use std::rc::Rc; // Non-thread-safe reference counting
use std::thread;

fn main() {
    let counter = Rc::new(0);

    let handle = thread::spawn(move || {
        // ERROR: `Rc<i32>` cannot be sent between threads safely.
        println!("{}", counter); 
    });

    handle.join().unwrap();
}
```

---

### Summary

| Feature | Garbage Collection (Go/Java) | Rust Ownership/Borrowing |
| :--- | :--- | :--- |
| **Memory Safety** | Runtime (Prevents use-after-free) | Compile-time (Borrow Checker) |
| **Data Races** | Possible (Requires runtime locks) | Impossible in Safe Rust (Enforced by types) |
| **Performance** | Non-deterministic (GC pauses) | Deterministic (No runtime, RAII cleanup) |
| **Thread Safety** | Programmer's responsibility | Enforced by `Send`/`Sync` traits |

### Conclusion
Rust is preferred for concurrency when **latency, throughput, and absolute safety** are priorities. By shifting memory management and synchronization checks to compile time, Rust eliminates an entire class of runtime bugs and removes the performance tax of a garbage collector. However, for applications where rapid development is prioritized over micro-optimizations (e.g., standard CRUD web apps), GC languages remain a highly productive choice.

# Rate Limiting Without Blocking the Event Loop

To rate limit requests without blocking the event loop, you must avoid synchronous delays (like `time.sleep()` in Python or `while` loops with `Date.now()` in JavaScript). Instead, use non-blocking, asynchronous techniques that yield control back to the event loop. 

Below are the most effective strategies, covering both fixed concurrency and strict requests-per-second limits.

---

## 1. The Worker Queue (Best for Fixed Concurrency)
If you need to process a large list of tasks (like scraping URLs) without overwhelming the server, a queue-based worker pattern is ideal. It limits **concurrency** (how many requests happen at once) and is highly memory efficient.

**Python (`asyncio` + `httpx`):**
```python
import asyncio
import httpx

async def worker(name, queue, client):
    while True:
        url = await queue.get()
        try:
            print(f"Worker {name} processing {url}")
            response = await client.get(url)
            print(f"Worker {name} got {response.status_code}")
        except Exception as e:
            print(f"Worker {name} failed: {e}")
        finally:
            queue.task_done()

async def main():
    urls = [f"https://httpbin.org/get?id={i}" for i in range(20)]
    queue = asyncio.Queue()
    for url in urls:
        queue.put_nowait(url)

    # Limit concurrency to 3 workers
    async with httpx.AsyncClient() as client:
        tasks = []
        for i in range(3):
            task = asyncio.create_task(worker(f"worker-{i}", queue, client))
            tasks.append(task)

        await queue.join() # Wait until queue is empty
        for task in tasks:
            task.cancel()

asyncio.run(main())
```

---

## 2. Token Bucket Algorithm (Best for Rate-per-Second)
If you need to ensure you don't exceed **X requests per second (RPS)**, use a token bucket or sliding window algorithm. This ensures a strict gap or limit between requests.

**JavaScript (Node.js):**
```javascript
class TokenBucket {
  constructor(tokensPerInterval, intervalMs) {
    this.tokens = tokensPerInterval;
    this.maxTokens = tokensPerInterval;
    this.intervalMs = intervalMs;
    this.lastRefill = Date.now();
  }

  refill() {
    const now = Date.now();
    const elapsed = now - this.lastRefill;
    const tokensToAdd = Math.floor((elapsed / this.intervalMs) * this.maxTokens);
    if (tokensToAdd > 0) {
      this.tokens = Math.min(this.maxTokens, this.tokens + tokensToAdd);
      this.lastRefill = now;
    }
  }

  async acquire() {
    this.refill();
    if (this.tokens > 0) {
      this.tokens--;
      return true;
    }
    // Non-blocking wait
    const waitTime = this.intervalMs - (Date.now() - this.lastRefill);
    if (waitTime > 0) {
      await new Promise(resolve => setTimeout(resolve, waitTime));
    }
    this.refill();
    this.tokens--;
    return true;
  }
}

// Usage: 5 requests per second
const limiter = new TokenBucket(5, 1000);

async function makeRequest() {
  await limiter.acquire();
  // Execute request
}
```

**Python (`asyncio` with Lock):**
In Python, you can achieve a similar rate-per-second limit using `asyncio.sleep()` and an `asyncio.Lock()` to prevent bursts.
```python
import asyncio
import time

class RateLimiter:
    def __init__(self, requests_per_second):
        self.delay = 1.0 / requests_per_second
        self.last_call = 0
        self.lock = asyncio.Lock()

    async def wait(self):
        async with self.lock:
            elapsed = time.perf_counter() - self.last_call
            wait_time = self.delay - elapsed
            if wait_time > 0:
                await asyncio.sleep(wait_time) # Non-blocking sleep
            self.last_call = time.perf_counter()
```

---

## 3. Express Middleware (Per-Client Rate Limiting)
If you are building an API and need to limit requests per client (e.g., by IP), you can implement middleware using a sliding window approach.

**JavaScript (Node.js/Express):**
```javascript
class PerClientLimiter {
  constructor(maxRequests, windowMs) {
    this.maxRequests = maxRequests;
    this.windowMs = windowMs;
    this.clients = new Map();
  }

  middleware() {
    return (req, res, next) => {
      const ip = req.ip;
      const now = Date.now();

      if (!this.clients.has(ip)) {
        this.clients.set(ip, { count: 1, startTime: now });
        return next();
      }

      const client = this.clients.get(ip);
      if (now - client.startTime > this.windowMs) {
        client.count = 1;
        client.startTime = now;
        return next();
      }

      if (client.count >= this.maxRequests) {
        const retryAfter = Math.ceil((this.windowMs - (now - client.startTime)) / 1000);
        res.set('Retry-After', retryAfter);
        return res.status(429).json({ error: 'Too Many Requests' });
      }

      client.count++;
      next();
    };
  }
}
```

---

## 4. Established Libraries
For production environments, it is highly recommended to use battle-tested libraries that handle edge cases and distributed memory (like Redis) out of the box.

*   **Node.js:** `express-rate-limit` (simple API limiting), `bottleneck` (advanced job throttling), or `rate-limiter-flexible` (supports Redis).
*   **Python:** `aiolimiter` or `httpx` with native concurrency limits.

---

## Key Best Practices
*   **Do use non-blocking sleeps:** `await asyncio.sleep()` in Python or `await new Promise(resolve => setTimeout(resolve, ms))` in JavaScript. These yield control to the event loop, allowing other tasks to run.
*   **Don't use synchronous delays:** `time.sleep()` in Python or `while` loops checking `Date.now()` in JavaScript block the entire thread.
*   **Use Locks:** In Python, use `asyncio.Lock()` around rate-limiting logic. Without it, multiple coroutines might check the timestamp simultaneously and all decide to proceed, causing a burst.
*   **Clean up old entries:** If tracking timestamps per client, periodically filter out old entries to prevent memory leaks.
*   **Distributed Systems:** For multi-instance deployments, rely on Redis-based rate limiting rather than in-memory limits to ensure accuracy across all instances.

There is no single "best" way, but the **industry standard** is a **Defense-in-Depth strategy** combining:
1.  **Client-Side Validation**: For immediate UX feedback (speed).
2.  **Server-Side Validation**: For security (trust).
3.  **Declarative Constraints**: Using native OS features where possible.

Below is a robust implementation pattern using **React Native** (conceptually applicable to Flutter/Swift/Kotlin) that demonstrates this layered approach.

### Key Principles
*   **Never trust the client**: Always validate on the backend.
*   **Fail Fast**: Catch errors before network requests.
*   **Sanitize**: Clean input to prevent injection attacks.
*   **Feedback**: Show clear, context-aware error messages.

---

### Code Example: React Native with Custom Hook
This example validates an email and password using a custom hook, separating logic from UI.

#### 1. The Validation Logic (`useFormValidation.ts`)
We define strict rules and a reusable hook.

```typescript
import { useState, useCallback } from 'react';

// Define validation rules
type ValidationRule = (value: string) => string | null;

const rules = {
  email: (value: string): string | null => {
    if (!value) return 'Email is required';
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(value)) return 'Please enter a valid email address';
    return null;
  },
  password: (value: string): string | null => {
    if (!value) return 'Password is required';
    if (value.length < 8) return 'Password must be at least 8 characters';
    if (!/[A-Z]/.test(value)) return 'Must include an uppercase letter';
    if (!/[0-9]/.test(value)) return 'Must include a number';
    return null;
  },
};

export const useFormValidation = () => {
  const [errors, setErrors] = useState<Record<string, string>>({});
  const [isValid, setIsValid] = useState(false);

  const validateField = useCallback((field: string, value: string) => {
    const rule = rules[field as keyof typeof rules];
    const error = rule ? rule(value) : null;

    setErrors((prev) => {
      const newErrors = { ...prev };
      if (error) {
        newErrors[field] = error;
      } else {
        delete newErrors[field];
      }
      return newErrors;
    });

    return error === null;
  }, []);

  const validateAll = (data: Record<string, string>) => {
    const newErrors: Record<string, string> = {};
    let allValid = true;

    Object.keys(data).forEach((key) => {
      const rule = rules[key as keyof typeof rules];
      if (rule) {
        const error = rule(data[key]);
        if (error) {
          newErrors[key] = error;
          allValid = false;
        }
      }
    });

    setErrors(newErrors);
    setIsValid(allValid);
    return allValid;
  };

  return { errors, validateField, validateAll, isValid, setErrors };
};
```

#### 2. The UI Implementation (`LoginScreen.tsx`)
This component uses native keyboard types for basic constraint and the hook for complex logic.

```tsx
import React, { useState } from 'react';
import { View, Text, TextInput, Button, StyleSheet, Alert } from 'react-native';
import { useFormValidation } from './useFormValidation';

const LoginScreen = () => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const { errors, validateField, validateAll } = useFormValidation();
  const [isSubmitting, setIsSubmitting] = useState(false);

  const handleSubmit = async () => {
    // 1. Client-side validation check
    const isFormValid = validateAll({ email, password });

    if (!isFormValid) {
      // Stop here if client validation fails
      return; 
    }

    setIsSubmitting(true);

    try {
      // 2. Send to Server (Server MUST validate again)
      const response = await fetch('https://api.example.com/login', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email, password }),
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.message || 'Login failed');
      }

      Alert.alert('Success', 'Logged in successfully!');
    } catch (error: any) {
      Alert.alert('Error', error.message);
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <View style={styles.container}>
      {/* Email Input with Native Keyboard Constraint */}
      <TextInput
        style={styles.input}
        placeholder="Email"
        keyboardType="email-address" // Native OS validation hint
        autoCapitalize="none"
        value={email}
        onChangeText={(text) => {
          setEmail(text);
          if (errors.email) validateField('email', text); // Clear error on type
        }}
      />
      {errors.email && <Text style={styles.error}>{errors.email}</Text>}

      {/* Password Input */}
      <TextInput
        style={styles.input}
        placeholder="Password"
        secureTextEntry
        value={password}
        onChangeText={(text) => {
          setPassword(text);
          if (errors.password) validateField('password', text);
        }}
      />
      {errors.password && <Text style={styles.error}>{errors.password}</Text>}

      <Button 
        title={isSubmitting ? "Loading..." : "Login"} 
        onPress={handleSubmit} 
        disabled={isSubmitting}
      />
    </View>
  );
};

const styles = StyleSheet.create({
  container: { padding: 20, flex: 1, justifyContent: 'center' },
  input: { borderWidth: 1, borderColor: '#ccc', padding: 10, marginBottom: 5, borderRadius: 5 },
  error: { color: 'red', fontSize: 12, marginBottom: 10 },
});

export default LoginScreen;
```

### Why this is the "Best" Approach

1.  **Native Keyboard Types (`keyboardType="email-address"`)**:
    *   *Benefit*: Changes the mobile keyboard layout (adds `@` symbol), reducing typing errors immediately at the OS level.
2.  **Real-time Feedback (`onChangeText`)**:
    *   *Benefit*: Clears error messages as soon as the user starts correcting the mistake, improving UX.
3.  **Centralized Logic (`useFormValidation`)**:
    *   *Benefit*: Keeps validation rules consistent across the app and makes them easy to unit test.
4.  **Server-Side Redundancy**:
    *   *Benefit*: The `handleSubmit` function assumes the client check passed, but the code comment emphasizes that the API endpoint **must** run the same regex/logic. If a hacker bypasses the mobile app and hits the API directly, the server stops them.

### Recommended Libraries for Production
If you don't want to write custom regex logic, use these battle-tested libraries:

*   **React Native**: `react-hook-form` + `zod` (for schema validation).
*   **Flutter**: `flutter_form_builder` + `validators` package.
*   **iOS (Swift)**: Combine framework with `Result` builders or libraries like `ValidationKit`.
*   **Android (Kotlin)**: Jetpack Compose `TextField` state flows combined with sealed classes for error states.

**Example with Zod (React Native):**
```typescript
import { z } from "zod";

const loginSchema = z.object({
  email: z.string().email("Invalid email address"),
  password: z.string().min(8, "Password too short"),
});

// Usage
try {
  loginSchema.parse({ email: "bad", password: "123" });
} catch (e) {
  // Handle structured errors automatically
}
```

Caching database queries in JavaScript depends heavily on your environment (Node.js backend vs. Browser) and your architecture. Since browsers generally cannot connect directly to databases for security reasons, caching is typically implemented on the **server-side (Node.js)**.

Here are the three most common approaches, ranging from simple in-memory caching to using dedicated caching layers like Redis.

### 1. In-Memory Caching (Simplest)
Best for: Small applications, single-server instances, or data that doesn't change often.
**Warning:** If you restart the server, the cache is lost. Also, in a multi-server setup (cluster), each server has its own separate cache, which can lead to inconsistency.

```javascript
// Simple in-memory cache object
const queryCache = new Map();
const CACHE_TTL = 60000; // 1 minute in milliseconds

async function getCachedUser(userId) {
  const cacheKey = `user:${userId}`;
  const cachedData = queryCache.get(cacheKey);

  // Check if cache exists and is not expired
  if (cachedData && Date.now() < cachedData.expiry) {
    console.log('📦 Serving from memory cache');
    return cachedData.data;
  }

  // If not in cache, fetch from DB
  console.log('💾 Fetching from database...');
  const user = await db.query('SELECT * FROM users WHERE id = $1', [userId]);

  // Store in cache
  queryCache.set(cacheKey, {
    data: user,
    expiry: Date.now() + CACHE_TTL
  });

  return user;
}

// Optional: Clean up expired entries periodically
setInterval(() => {
  const now = Date.now();
  for (const [key, value] of queryCache.entries()) {
    if (now > value.expiry) {
      queryCache.delete(key);
    }
  }
}, 10000); // Run every 10 seconds
```

### 2. Using Redis (Production Standard)
Best for: Production environments, multi-server setups, and high-traffic applications. Redis is an external in-memory data store that persists across server restarts and is shared among all instances.

You will need the `redis` package:
`npm install redis`

```javascript
const { createClient } = require('redis');
const db = require('./your-db-connection'); // Your existing DB logic

const redisClient = createClient({
  url: 'redis://localhost:6379'
});

redisClient.on('error', (err) => console.error('Redis Client Error', err));

async function initCache() {
  await redisClient.connect();
}

async function getCachedProducts(category) {
  const cacheKey = `products:${category}`;

  try {
    // Try to get from Redis
    const cachedData = await redisClient.get(cacheKey);

    if (cachedData) {
      console.log('📦 Serving from Redis');
      return JSON.parse(cachedData);
    }

    // Cache miss: Fetch from DB
    console.log('💾 Fetching from database...');
    const results = await db.query('SELECT * FROM products WHERE category = $1', [category]);

    // Set in Redis with expiration (e.g., 5 minutes = 300 seconds)
    await redisClient.setEx(cacheKey, 300, JSON.stringify(results));

    return results;
  } catch (error) {
    console.error('Cache error, falling back to DB:', error);
    // Fallback: Return directly from DB if Redis fails
    return await db.query('SELECT * FROM products WHERE category = $1', [category]);
  }
}

// Initialize
initCache();
```

### 3. Automatic Caching with a Library (Prisma + prisma-cache)
If you are using an ORM like Prisma, you can use middleware or specific libraries to handle caching logic automatically so you don't have to wrap every query manually.

Example concept using a generic wrapper pattern:

```javascript
class CachedRepository {
  constructor(dbClient, cacheClient) {
    this.db = dbClient;
    this.cache = cacheClient; // Could be Redis or Map
  }

  async query(sql, params, key, ttlSeconds = 300) {
    // 1. Check Cache
    if (this.cache.get) { // Check if Redis client
      const cached = await this.cache.get(key);
      if (cached) return JSON.parse(cached);
    } else if (this.cache.has(key)) { // Check if Map
       const item = this.cache.get(key);
       if (Date.now() < item.expiry) return item.data;
    }

    // 2. Execute DB Query
    const result = await this.db.query(sql, params);

    // 3. Save to Cache
    if (this.cache.setEx) {
      await this.cache.setEx(key, ttlSeconds, JSON.stringify(result));
    } else {
      this.cache.set(key, { data: result, expiry: Date.now() + (ttlSeconds * 1000) });
    }

    return result;
  }
}

// Usage
// const repo = new CachedRepository(db, redisClient);
// const users = await repo.query('SELECT * FROM users', [], 'all_users', 60);
```

### Key Considerations for Implementation

1.  **Cache Invalidation**: This is the hardest part. When you update a user in the database (`UPDATE users...`), you must delete or update the corresponding cache key (`DEL user:123`), otherwise, users will see stale data.
2.  **Cache Stampede**: If many requests come in simultaneously for a missing key, they might all hit the database at once before the cache is populated. Use "locking" or probabilistic early expiration to prevent this.
3.  **Sensitive Data**: Never cache sensitive information (passwords, PII) unless the cache layer is encrypted and strictly access-controlled.
4.  **Serialization**: Redis stores everything as strings. Always `JSON.stringify()` before saving and `JSON.parse()` after retrieving complex objects.

**Recommendation:**
*   For **development/small tools**: Use the **In-Memory (Map)** approach.
*   For **production**: Use **Redis**. It provides persistence, sharing across servers, and advanced data structures.

To build a client for a real-time WebSocket stream alongside a REST API, you need a **Hybrid Architecture**. REST is stateless and request-response based, making it ideal for control operations like authentication or fetching historical data. WebSockets are stateful and full-duplex, making them perfect for live data delivery. You cannot "REST" a WebSocket; instead, you combine both.

Here is the industry-standard pattern and a complete implementation using **Node.js** and **TypeScript**.

### Architecture Pattern
```
┌─────────────────────────────────────────┐
│              Client Application          │
├─────────────────┬───────────────────────┤
│   REST Client   │   WebSocket Client    │
│   (CRUD ops)    │   (Real-time stream)  │
└────────┬────────┴──────────┬────────────┘
         │                   │
         ▼                   ▼
    HTTP/HTTPS          WebSocket
```

### Complete Implementation

#### 1. Install dependencies
```bash
npm install ws axios
npm install --save-dev @types/ws @types/node typescript ts-node
```

#### 2. The Client Code (`streamClient.ts`)

```typescript
import WebSocket from 'ws';
import axios from 'axios';
import { EventEmitter } from 'events';

interface StreamConfig {
    restBaseUrl: string;
    wsUrl: string;
    apiKey: string;
}

class RealTimeClient extends EventEmitter {
    private socket: WebSocket | null = null;
    private authToken: string | null = null;
    private reconnectAttempts = 0;
    private maxReconnectAttempts = 5;
    private messageQueue: object[] = [];

    constructor(private config: StreamConfig) {
        super();
    }

    // ========== REST Methods ==========

    /**
     * STEP 1: REST Call to authenticate and get a session token
     */
    async authenticate() {
        try {
            const response = await axios.post(`${this.config.restBaseUrl}/auth`, {
                apiKey: this.config.apiKey
            });
            this.authToken = response.data.token;
            console.log('✅ Authenticated successfully');
        } catch (error) {
            this.emit('error', new Error('Authentication failed'));
            throw error;
        }
    }

    async fetchData(endpoint: string) {
        const response = await axios.get(`${this.config.restBaseUrl}/${endpoint}`);
        return response.data;
    }

    // ========== WebSocket Methods ==========

    /**
     * STEP 2: Initialize WebSocket connection using the REST token
     */
    connect(): Promise<void> {
        return new Promise((resolve, reject) => {
            if (!this.authToken) throw new Error('Must authenticate before connecting');

            // Pass token via query string (standard practice)
            this.socket = new WebSocket(`${this.config.wsUrl}?token=${this.authToken}`);

            this.socket.on('open', () => {
                console.log('🔌 WebSocket Connected');
                this.reconnectAttempts = 0;
                this.flushQueue();
                this.emit('connection', { status: 'connected' });
                resolve();
            });

            this.socket.on('message', (data: WebSocket.Data) => {
                try {
                    const parsed = JSON.parse(data.toString());
                    const eventType = parsed.type || 'message';
                    this.emit(eventType, parsed.payload);
                } catch (e) {
                    this.emit('error', new Error('Failed to parse message'));
                }
            });

            this.socket.on('close', () => {
                console.log('❌ Disconnected. Attempting reconnect...');
                this.emit('connection', { status: 'disconnected' });
                this.reconnect();
            });

            this.socket.on('error', (err) => {
                this.emit('error', err);
                reject(err);
            });
        });
    }

    /**
     * STEP 3: Send "Command" over WebSocket
     */
    send(data: object): void {
        if (this.socket?.readyState === WebSocket.OPEN) {
            this.socket.send(JSON.stringify(data));
        } else {
            this.messageQueue.push(data); // Prevent data loss during disconnection
        }
    }

    subscribe(topic: string) {
        this.send({ action: 'subscribe', topic });
        console.log(`📡 Subscribed to ${topic}`);
    }

    private flushQueue(): void {
        while (this.messageQueue.length > 0 && this.socket?.readyState === WebSocket.OPEN) {
            this.socket.send(JSON.stringify(this.messageQueue.shift()!));
        }
    }

    private reconnect(): void {
        if (this.reconnectAttempts < this.maxReconnectAttempts) {
            this.reconnectAttempts++;
            const delay = Math.min(1000 * Math.pow(2, this.reconnectAttempts), 30000);
            console.log(`Reconnecting in ${delay}ms (attempt ${this.reconnectAttempts})`);
            setTimeout(() => this.connect(), delay);
        } else {
            console.error('Max reconnection attempts reached');
        }
    }

    disconnect() {
        this.socket?.close();
        this.socket = null;
    }
}

// --- Usage Example ---

const client = new RealTimeClient({
    restBaseUrl: 'https://api.example.com',
    wsUrl: 'wss://stream.example.com',
    apiKey: 'your_secret_key'
});

client.on('ticker', (data) => console.log('📈 Price Update:', data));
client.on('connection', (status) => console.log('Connection status:', status));
client.on('error', (err) => console.error('🚨 Client Error:', err));

async function start() {
    try {
        await client.authenticate();
        await client.connect();

        // Once connected, subscribe to a specific feed
        client.subscribe('BTC-USD');

        // Fetch historical data via REST
        const history = await client.fetchData('history');
        console.log('Historical data:', history);
    } catch (e) {
        console.error('Startup failed', e);
    }
}

start();
```

### Key Engineering Decisions Explained

#### 1. The `EventEmitter` Pattern
Instead of putting business logic inside the `on('message')` callback, we extend `EventEmitter`. This allows other parts of your app to do this: `client.on('trade', handleTrade)`. This decouples the **transport layer** (WebSocket) from the **application layer**.

#### 2. Token-Based Handshake
You should **never** send your API Key directly over a WebSocket. 
*   **Wrong:** `wss://stream.com?apiKey=123`
*   **Right:** Use REST to trade your API Key for a short-lived **JWT/Session Token**, then pass that token to the WebSocket.

#### 3. Message Queuing
If the WebSocket connection drops, messages sent via `client.send()` are pushed to `messageQueue`. When the connection is re-established, `flushQueue()` processes them, preventing data loss during network flickers.

#### 4. Error Handling & Exponential Backoff
The `reconnect()` method ensures that if the server restarts or the network flickers, the client automatically recovers. By using **Exponential Backoff** (wait 1s, then 2s, then 4s...), you avoid DDOSing your own server during an outage.

### Summary Table
| Feature | REST Part | WebSocket Part |
| :--- | :--- | :--- |
| **Auth** | `POST /login` → Token | `wss://...?token=XYZ` |
| **Config** | `GET /settings` | N/A |
| **Data** | `GET /history` (Bulk) | `on('message')` (Incremental) |
| **Control** | `POST /update` | `socket.send({action: 'sub'})` |

This hybrid approach gives you the best of both worlds: reliable stateless operations for commands and persistent bidirectional communication for real-time updates. 🚀

# Webhook Validation in Rust

To securely validate incoming webhooks in Rust, the most common and recommended approach is **HMAC signature verification**. This ensures that the request originated from a trusted source and hasn't been tampered with.

The most critical rule is: **You must verify the signature using the raw request body**, not parsed JSON. Any change in whitespace or key order during parsing will invalidate the hash.

## 1. Dependencies

Add these to your `Cargo.toml`:

```toml
[dependencies]
axum = "0.7"
tokio = { version = "1", features = ["full"] }
serde = { version = "1", features = ["derive"] }
serde_json = "1"
hmac = "0.12"
sha2 = "0.10"
hex = "0.4"
base64 = "0.21"
time = { version = "0.3", features = ["macros"] }
constant_time_eq = "0.3"
thiserror = "1"
stripe = { version = "0.20", features = ["webhook"] }
```

## 2. Generic HMAC Validation Utility

Here is a complete implementation using **Axum** and **RustCrypto**. This utility handles the raw bytes, strips common prefixes (like `sha256=`), and uses constant-time comparison to prevent timing attacks.

```rust
use axum::{
    body::Bytes,
    extract::State,
    http::{HeaderMap, StatusCode},
    response::IntoResponse,
    routing::post,
    Router,
};
use hmac::{Hmac, Mac};
use sha2::Sha256;
use time::OffsetDateTime;

type HmacSha256 = Hmac<Sha256>;

#[derive(Clone)]
pub struct AppState {
    pub webhook_secret: String,
}

pub fn verify_signature(secret: &str, body: &[u8], signature_header: &str) -> bool {
    // Some providers prefix the signature (e.g., "sha256=abc123..."). 
    // We need to remove that prefix if it exists.
    let signature_hex = signature_header
        .strip_prefix("sha256=")
        .unwrap_or(signature_header);

    // Convert the hex string signature into bytes
    let expected_sig = match hex::decode(signature_hex) {
        Ok(sig) => sig,
        Err(_) => return false,
    };

    // Initialize HMAC with the secret key
    let mut mac = match HmacSha256::new_from_slice(secret.as_bytes()) {
        Ok(mac) => mac,
        Err(_) => return false,
    };

    // Update the HMAC with the raw body bytes
    mac.update(body);

    // Verify the computed MAC against the provided signature.
    // .verify_slice() uses constant-time comparison to prevent timing attacks.
    mac.verify_slice(&expected_sig).is_ok()
}
```

## 3. GitHub Webhook Validation Example

GitHub sends a signature in the `x-hub-signature-256` header and hashes the raw payload directly.

```rust
pub async fn github_webhook_handler(
    State(state): State<AppState>,
    headers: HeaderMap,
    body: Bytes, // We take raw bytes to verify the signature
) -> impl IntoResponse {
    // 1. Get the signature from the headers
    let signature_header = match headers.get("x-hub-signature-256") {
        Some(value) => value.to_str().unwrap_or(""),
        None => return StatusCode::BAD_REQUEST.into_response(),
    };

    // 2. Validate the signature
    if !verify_signature(&state.webhook_secret, &body, signature_header) {
        eprintln!("GitHub webhook validation failed");
        return StatusCode::UNAUTHORIZED.into_response();
    }

    // 3. Process the payload
    println!("Valid GitHub webhook received");

    StatusCode::OK.into_response()
}
```

## 4. Stripe Webhook Validation (with Timestamp)

Stripe includes a timestamp in the `stripe-signature` header (`t=timestamp,v1=hash`). You must include the timestamp in the HMAC payload and validate its freshness to prevent replay attacks. Using the official `stripe` crate simplifies this:

```rust
use stripe::{Event, Webhook};

const TOLERANCE_SECONDS: i64 = 300; // 5 minutes

pub async fn stripe_webhook_handler(
    headers: HeaderMap,
    body: Bytes, // We take raw bytes to verify the signature
) -> impl IntoResponse {
    let sig_header = match headers.get("stripe-signature") {
        Some(val) => val.to_str().unwrap_or(""),
        None => return StatusCode::BAD_REQUEST.into_response(),
    };

    let secret = std::env::var("STRIPE_WEBHOOK_SECRET")
        .expect("STRIPE_WEBHOOK_SECRET must be set");

    // The stripe crate handles timestamp validation and constant-time comparison
    let event: Event = match Webhook::construct_event(&body, sig_header, &secret) {
        Ok(event) => event,
        Err(e) => {
            eprintln!("Stripe webhook validation failed: {}", e);
            return StatusCode::UNAUTHORIZED.into_response();
        }
    };

    println!("Received Stripe event: {}", event.type_);
    StatusCode::OK.into_response()
}
```

## 5. Server Setup

```rust
#[tokio::main]
async fn main() {
    let state = AppState {
        webhook_secret: std::env::var("WEBHOOK_SECRET")
            .expect("WEBHOOK_SECRET must be set"),
    };

    let app = Router::new()
        .route("/webhooks/github", post(github_webhook_handler))
        .route("/webhooks/stripe", post(stripe_webhook_handler))
        .with_state(state);

    let listener = tokio::net::TcpListener::bind("0.0.0.0:3000")
        .await
        .unwrap();
    println!("Listening on :3000");
    axum::serve(listener, app).await.unwrap();
}
```

## 6. Common Provider Variations

Different providers use slightly different formats for their signatures:

| Provider | Header Name | Format | Note |
| :--- | :--- | :--- | :--- |
| **GitHub** | `x-hub-signature-256` | `sha256=hash` | Hex encoded |
| **Stripe** | `stripe-signature` | `t=timestamp,v1=hash` | Hex encoded, includes timestamp |
| **Shopify** | `x-shopify-hmac-sha256` | `hash` | Base64 encoded instead of Hex |

**If your provider uses Base64 instead of Hex:**
Replace `hex::decode(signature_hex)` with:
```rust
use base64::{engine::general_purpose, Engine as _};
let expected_sig = general_purpose::STANDARD.decode(signature_hex).unwrap();
```

## 7. Best Practices

- ✅ **Use constant-time comparison:** Never use `==` to compare signatures. Standard comparison returns early on mismatch, allowing attackers to guess the signature byte-by-byte by measuring response times (Timing Attack).
- ✅ **Validate timestamps:** Ensure timestamps are within a reasonable tolerance (e.g., 5 minutes) to prevent replay attacks.
- ✅ **Raw Body Access:** Always take `body: Bytes` instead of `Json<T>` in your handler so the signature is verified against the exact bytes received.
- ✅ **Secure Secrets:** Store secrets securely using environment variables or a secret manager, never hardcode them.
- ✅ **HTTPS Only:** Always use HTTPS for webhook endpoints to protect data in transit.
- ✅ **Log Failures:** Log validation failures for monitoring and debugging, returning `4xx` errors to the caller.

# Circuit Breakers with OpenTelemetry

## ⚠️ Important Clarification

**OpenTelemetry (OTel) does NOT provide circuit breaker functionality.** It is strictly an observability framework for tracing, metrics, and logs. A circuit breaker is a stability pattern. To achieve this, you use a resilience library (like Resilience4j, pybreaker, or opossum) to handle the logic, and OpenTelemetry to **observe** when the circuit opens, closes, or fails.

## Architecture

```
┌─────────────┐    ┌──────────────┐    ┌─────────────────┐
│   Service   │───▶│  Circuit     │───▶│  OpenTelemetry  │
│   Code      │    │  Breaker     │    │  (Metrics/Traces)│
└─────────────┘    └──────────────┘    └─────────────────┘
```

---

## Java Example (Resilience4j + OpenTelemetry)

### 1. Dependencies (`pom.xml`)
```xml
<dependencies>
    <!-- Resilience4j for Circuit Breaker logic -->
    <dependency>
        <groupId>io.github.resilience4j</groupId>
        <artifactId>resilience4j-circuitbreaker</artifactId>
        <version>2.1.0</version>
    </dependency>
    <!-- OpenTelemetry API -->
    <dependency>
        <groupId>io.opentelemetry</groupId>
        <artifactId>opentelemetry-api</artifactId>
        <version>1.32.0</version>
    </dependency>
</dependencies>
```

### 2. Implementation
```java
import io.github.resilience4j.circuitbreaker.*;
import io.opentelemetry.api.OpenTelemetry;
import io.opentelemetry.api.metrics.*;
import io.opentelemetry.api.trace.Tracer;
import io.opentelemetry.api.trace.Span;
import java.time.Duration;
import java.util.function.Supplier;

public class CircuitBreakerService {

    private final CircuitBreaker circuitBreaker;
    private final Tracer tracer;
    private final LongCounter callCounter;
    private final LongCounter failureCounter;
    private final DoubleGauge stateGauge;

    public CircuitBreakerService(OpenTelemetry openTelemetry) {
        this.tracer = openTelemetry.getTracer("circuit-breaker-tracer");
        Meter meter = openTelemetry.getMeter("circuit-breaker-meter");

        // Configure Circuit Breaker
        CircuitBreakerConfig config = CircuitBreakerConfig.custom()
            .failureRateThreshold(50)
            .waitDurationInOpenState(Duration.ofSeconds(30))
            .slidingWindowSize(10)
            .build();

        this.circuitBreaker = CircuitBreaker.of("backendService", config);

        // Setup OpenTelemetry Metrics
        this.callCounter = meter.counterBuilder("circuit_breaker_calls_total").build();
        this.failureCounter = meter.counterBuilder("circuit_breaker_failures_total").build();
        this.stateGauge = meter.gaugeBuilder("circuit_breaker_state")
            .buildWithCallback(measurement -> {
                measurement.record(getStateValue(), 
                    Attributes.builder().put("service", "backendService").build());
            });

        // Register event listeners
        circuitBreaker.getEventPublisher()
            .onSuccess(event -> callCounter.add(1, Attributes.builder().put("status", "success").build()))
            .onError(event -> {
                callCounter.add(1, Attributes.builder().put("status", "error").build());
                failureCounter.add(1, Attributes.builder().put("error_type", event.getThrowable().getClass().getSimpleName()).build());
            });
    }

    private double getStateValue() {
        switch (circuitBreaker.getState()) {
            case CLOSED: return 0;
            case OPEN: return 1;
            case HALF_OPEN: return 2;
            default: return 0;
        }
    }

    public String executeWithCircuitBreaker(Supplier<String> supplier) {
        Span span = tracer.spanBuilder("circuit-breaker-operation")
            .setAttribute("circuit.breaker.name", "backendService")
            .setAttribute("circuit.breaker.state", circuitBreaker.getState().name())
            .startSpan();

        try (var scope = span.makeCurrent()) {
            String result = circuitBreaker.executeSupplier(supplier);
            span.setAttribute("circuit.breaker.result", "success");
            return result;
        } catch (Exception e) {
            span.setAttribute("circuit.breaker.result", "failure");
            span.recordException(e);
            throw e;
        } finally {
            span.end();
        }
    }
}
```

---

## Python Example (pybreaker + OpenTelemetry)

### 1. Installation
```bash
pip install pybreaker opentelemetry-api opentelemetry-sdk
```

### 2. Implementation
```python
from pybreaker import CircuitBreaker
from opentelemetry import trace, metrics
from opentelemetry.sdk.trace import TracerProvider
from opentelemetry.sdk.metrics import MeterProvider

class CircuitBreakerWithOTel:
    def __init__(self):
        # Setup OpenTelemetry
        trace.set_tracer_provider(TracerProvider())
        self.tracer = trace.get_tracer("circuit-breaker")

        metrics.set_meter_provider(MeterProvider())
        self.meter = metrics.get_meter("circuit-breaker")

        # Create metrics
        self.call_counter = self.meter.create_counter("circuit_breaker_calls_total")
        self.failure_counter = self.meter.create_counter("circuit_breaker_failures_total")
        self.state_gauge = self.meter.create_gauge("circuit_breaker_state")

        # Setup Circuit Breaker
        self.breaker = CircuitBreaker(fail_max=5, reset_timeout=30, name="external_service")

    def execute(self, func, *args, **kwargs):
        with self.tracer.start_as_current_span("circuit_breaker_call") as span:
            span.set_attribute("circuit_breaker.name", self.breaker.name)
            span.set_attribute("circuit_breaker.state", self.breaker.current_state)

            # Record current state
            state_map = {"closed": 0, "open": 1, "half-open": 2}
            self.state_gauge.set(state_map.get(self.breaker.current_state, 0))

            try:
                result = self.breaker.call(func, *args, **kwargs)
                self.call_counter.add(1, {"status": "success"})
                span.set_attribute("circuit_breaker.result", "success")
                return result
            except Exception as e:
                self.call_counter.add(1, {"status": "error"})
                self.failure_counter.add(1, {"error_type": type(e).__name__})
                span.set_attribute("circuit_breaker.result", "failure")
                span.record_exception(e)
                raise
```

